    />
  );

  const valueSelector = (
    <FilterValueSelector<T>
      field={field}
      values={filter.values}
      operator={filter.operator}
      onChange={(values) => onUpdateFilter(filter.id, { values })}
      autoFocus={filter.id === lastAddedFilterId}
      open={valueSelectorOpen}
