      className="flex-1"
    />
  );

  const removeButton = (
    <FilterRemoveButton
      onClick={() => onRemoveFilter(filter.id)}
      aria-label={`${i18n.removeFilter}: ${field.label ?? ""}`.trim()}
    />
  );

  if (isMobile) {
    return (
      <div
        ref={chipRef}
        data-slot="filter-chip"
        aria-label={`${field.label ?? "Filter"} filter`}
        className="bg-muted-background flex w-full flex-col rounded-lg p-1"
