interface QuickActionsProps extends React.ComponentProps<"div"> {
  showEmpty?: boolean;
  returnPage?: string;
}

export const QuickActions = ({
  title,
  showEmpty: _showEmpty,
  returnPage,
  ...props
}: QuickActionsProps) => {
  const { t } = useTranslation();
  const [expanded, setExpanded] = useState(false);
