} from "./OrganizationsField";
import {
  DetailFormValues,
  questionnaireBasicSchema,
} from "./questionnaireFormSchema";
import { QuestionOverviewList } from "./QuestionOverviewList";
import { useUpdateQuestionnaire } from "./useUpdateQuestionnaire";
import { VersionsTab } from "./VersionsTab";

/** Move (not swap): removes the element at `from` and reinserts it at `to`,
 *  so drag-and-drop across several rows shifts the in-between rows instead
 *  of exchanging the two endpoints. */
function moveElement<T>(list: T[], from: number, to: number): T[] {
  const next = [...list];
  const [moved] = next.splice(from, 1);
  next.splice(to, 0, moved);
  return next;
}

export function QuestionnaireDetailPage({
  scope,
  id,
}: {
  scope: QuestionnaireScope;
  id: string;
}) {
  const { t } = useTranslation();
  const [cloneOpen, setCloneOpen] = useState(false);
  const [organizationDraft, setOrganizationDraft] =
    useState<OrganizationSelection | null>(null);
  // `?tab=versions` deep-links straight to the Versions tab — it's how the
  // revision page's Back button returns to the tab it was opened from.
  const [{ tab }] = useQueryParams();
  const { canWrite, isLoading: isPermissionLoading } =
    useCanWriteQuestionnaire(scope);

  const {
    data: questionnaire,
    isLoading,
    isError,
  } = useQuery({
    queryKey: questionnaireKeys.detail(id),
    queryFn: query(questionnaireApi.get, { pathParams: { id } }),
  });

  const detailSchema = useMemo(() => questionnaireBasicSchema(t), [t]);

  const form = useForm<DetailFormValues>({
    resolver: zodResolver(detailSchema),
    values: questionnaire
      ? {
          title: questionnaire.title,
          slug: questionnaire.slug,
          description: questionnaire.description ?? "",
          status: questionnaire.status,
        }
      : undefined,
    // Reordering questions saves through the same mutation and invalidates
    // questionnaireKeys.all, which refetches this detail query. Without
    // `keepDirtyValues`, the `values` binding above would reset every field
    // (including any unsaved, dirty title/slug/description/status edits) the
    // moment that refetch resolves.
    resetOptions: { keepDirtyValues: true },
  });

  // Owns the setQueryData-before-invalidate cache sequence and the success
  // toast (see the hook's doc comment).
  const { mutate: save, isPending } = useUpdateQuestionnaire(id);
  const dirty = form.formState.isDirty || organizationDraft !== null;
  useNavigationPrompt(dirty, t("unsaved_changes_warning"));

  const onSubmit = (values: DetailFormValues) => {
    if (!questionnaire) return;
    save(
      buildUpdateBody(questionnaire, {
        title: values.title,
        slug: values.slug,
        description: values.description,
        status: values.status,
      }),
      organizationDraft ? { scope, ...organizationDraft } : undefined,
      (updated) => {
        // This callback belongs to this successful save only. A failed save
        // followed by a reorder cannot clear the still-unsaved form.
        const live = form.getValues();
        if (
          Object.keys(values).every(
            (key) =>
              live[key as keyof DetailFormValues] ===
              values[key as keyof DetailFormValues],
          )
        ) {
          form.reset({
            title: updated.title,
            slug: updated.slug,
            description: updated.description ?? "",
            status: updated.status,
          });
        }
        setOrganizationDraft((current) =>
          current === organizationDraft ? null : current,
        );
      },
    );
  };

  // isPermissionLoading folds in so write affordances (Save Form, Edit
  // Questions, Clone…) don't pop in after the facility query resolves.
  if (isLoading || isPermissionLoading) {
    return <FormSkeleton rows={10} />;
  }

/**
 * @name field
 * @description A form field component with label, description, and error message support.
 * @dependencies class-variance-authority
 * @type registry:ui
 */
import { cva, type VariantProps } from "class-variance-authority";
import { useMemo } from "react";

import { TriangleAlert } from "lucide-react";

import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/lib/utils";

function FieldSet({ className, ...props }: React.ComponentProps<"fieldset">) {
  return (
    <fieldset
      data-slot="field-set"
      className={cn(
        "flex flex-col gap-6 has-[>[data-slot=checkbox-group]]:gap-3 has-[>[data-slot=radio-group]]:gap-3",
        className,
      )}
      {...props}
    />
  );
}

function FieldLegend({
  className,
  variant = "legend",
  ...props
}: React.ComponentProps<"legend"> & { variant?: "legend" | "label" }) {
  return (
    <legend
      data-slot="field-legend"
      data-variant={variant}
      className={cn(
        "mb-1.5 font-medium data-[variant=label]:text-sm data-[variant=legend]:text-base",
        className,
      )}
      {...props}
    />
  );
}

function FieldGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-group"
      className={cn(
        "group/field-group @container/field-group flex w-full flex-col gap-6 data-[slot=checkbox-group]:gap-3 *:data-[slot=field-group]:gap-4",
        className,
      )}
      {...props}
    />
  );
}

const fieldVariants = cva(
  "data-[invalid=true]:text-destructive group/field flex w-full",
  {
    variants: {
      orientation: {
        vertical: "gap-1 flex-col *:w-full [&>.sr-only]:w-auto",
        horizontal:
          "gap-2 flex-row items-center *:data-[slot=field-label]:flex-auto has-[>[data-slot=field-content]]:items-start has-[>[data-slot=field-content]]:[&>[role=checkbox],[role=radio]]:mt-px",
        responsive:
          "gap-1 flex-col *:w-full [&>.sr-only]:w-auto @md/field-group:flex-row @md/field-group:items-center @md/field-group:gap-2 @md/field-group:*:w-auto @md/field-group:*:data-[slot=field-label]:flex-auto @md/field-group:has-[>[data-slot=field-content]]:items-start @md/field-group:has-[>[data-slot=field-content]]:[&>[role=checkbox],[role=radio]]:mt-px",
      },
    },
    defaultVariants: {
      orientation: "vertical",
    },
  },
);

function Field({
  className,
  orientation = "vertical",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof fieldVariants>) {
  return (
    <div
      role="group"
      data-slot="field"
      data-orientation={orientation}
      className={cn(fieldVariants({ orientation }), className)}
      {...props}
    />
  );
}

function FieldContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-content"
      className={cn(
        "group/field-content flex flex-1 flex-col gap-1 leading-snug",
        className,
      )}
      {...props}
    />
  );
}

function FieldLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      data-slot="field-label"
      className={cn(
        "has-data-checked:text-primary-950 has-data-checked:bg-primary-50 has-data-checked:border-primary-600 dark:has-data-checked:text-primary-300 dark:has-data-checked:border-primary-500/50 dark:has-data-checked:bg-primary-950/70 group/field-label peer/field-label flex w-fit gap-2 leading-snug group-data-[disabled=true]/field:opacity-50 has-[>[data-slot=field]]:rounded-md has-[>[data-slot=field]]:border *:data-[slot=field]:p-3",
        "has-[>[data-slot=field]]:w-full has-[>[data-slot=field]]:flex-col",
        className,
      )}
      {...props}
    />
  );
}

function FieldTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-label"
      className={cn(
        "flex w-fit items-center gap-2 text-sm leading-snug font-medium group-data-[disabled=true]/field:opacity-50",
        className,
      )}
      {...props}
    />
  );
}

function FieldDescription({ className, ...props }: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="field-description"
      className={cn(
        "text-soft-foreground text-left text-sm leading-normal font-normal group-has-data-horizontal/field:text-balance [[data-variant=legend]+&]:-mt-1.5",
        "last:mt-0 nth-last-2:-mt-1",
        "[&>a:hover]:text-primary [&>a]:underline [&>a]:underline-offset-4",
        className,
      )}
      {...props}
    />
  );
}

function FieldSeparator({
  children,
  className,
  ...props
}: React.ComponentProps<"div"> & {
  children?: React.ReactNode;
}) {
  return (
    <div
      data-slot="field-separator"
      data-content={!!children}
      className={cn(
        "relative -my-2 h-5 text-sm group-data-[variant=outline]/field-group:-mb-2",
        className,
      )}
      {...props}
    >
      <Separator className="absolute inset-0 top-1/2" />
      {children && (
        <span
          className="text-muted-foreground bg-background relative mx-auto block w-fit px-2"
          data-slot="field-separator-content"
        >
          {children}
        </span>
      )}
    </div>
  );
}

function FieldError({
  className,
  children,
  errors,
  ...props
}: React.ComponentProps<"div"> & {
  errors?: Array<{ message?: string } | undefined>;
}) {
  const content = useMemo(() => {
    if (children) {
      return children;
    }

    if (!errors?.length) {
      return null;
    }

    const uniqueErrors = [
      ...new Map(errors.map((error) => [error?.message, error])).values(),
    ];

    if (uniqueErrors?.length == 1) {
      return uniqueErrors[0]?.message;
    }

    return (
      <ul className="ml-4 flex list-disc flex-col gap-1">
        {uniqueErrors.map(
          (error, index) =>
            error?.message && <li key={index}>{error.message}</li>,
        )}
      </ul>
    );
  }, [children, errors]);

  if (!content) {
    return null;
  }

  return (
    <div
      role="alert"
      data-slot="field-error"
      className={cn(
        "text-destructive bg-destructive/10 inline-flex max-w-fit items-start gap-1 rounded px-1.5 text-sm font-normal",
        className,
      )}
      {...props}
    >
      <TriangleAlert className="mt-0.5 size-3.5 shrink-0" />
      {content}
    </div>
  );
}

export {
  Field,
  FieldContent,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
  FieldLegend,
  FieldSeparator,
  FieldSet,
  FieldTitle,
};

