          <dd className="inline">{record.created_by?.username}</dd>
        </div>
      )}
      {(record.updated_by || record.modified_date) && (
        <div>
          <dt className="inline font-medium">{t("last_modified_by")}: </dt>
          <dd className="inline">
            {record.updated_by?.username}
            {record.modified_date && (
              <>
                {" "}
                ·{" "}
                <time dateTime={record.modified_date}>
                  {formatDateTime(record.modified_date)}
                </time>
              </>
            )}
          </dd>
        </div>
      )}
    </dl>
  );

  return (
    <div className="max-w-3xl space-y-4">
      <h2 className="text-lg font-semibold text-gray-900">
        {t("version_history")}
      </h2>

      {isLoading ? (
        <FormSkeleton rows={4} />
      ) : (
        <div className="flex flex-col">
          <div className="flex gap-4">
            <TimelineRail current isFirst isLast={false} />
            <div className="min-w-0 flex-1 pb-6">
              <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-gray-200 bg-white p-4">
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="font-medium text-gray-900">
                      {formatRevision(questionnaire.internal_revision)}
                    </span>
                    <Badge
                      variant={
                        QUESTIONNAIRE_STATUS_COLORS[questionnaire.status]
                      }
                    >
                      {t(questionnaire.status)}
                    </Badge>
                  </div>
                  {auditDetails(questionnaire)}
